import numpy as np

def zero_insert_image_freqs(omega0, L):
    image_freqs = np.array([omega0 + (2 * np.pi * k) / L for k in range(L)])
    image_freqs = np.mod(image_freqs, 2 * np.pi)
    image_freqs = image_freqs[image_freqs <= np.pi]
    return np.sort(image_freqs)

import numpy as np

def zero_insert_image_freqs(omega0, L):
    image_frequencies = np.sort(np.abs(np.fft.fftfreq(L, 1/L) * 2 * np.pi))
    image_frequencies = np.mod(image_frequencies + omega0, np.pi)
    return np.sort(image_frequencies)
